use super::*;
use crate::cn::wps::moss::{app::{KmoBookApi::KmoBookApi,event::KmoBookChangeEventsListener::KmoBookChangeEventsListener},xlsxr::{handler::WorkbookHandler::WorkbookHandler,xl::XlsxrWorkbook::XlsxrWorkbook,util::{UnifiedXmlReader::UnifiedXmlReader,ValueHelper::ValueHelper}}};
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let name=["NullPointerException","IllegalArgumentException","ArrayIndexOutOfBoundsException","RuntimeException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":name})}}}
fn verifier(m:&ModifyVerifier)->Value{json!({"hash":m.getHashData(),"salt":m.getSaltData(),"spin":m.getSpinCount(),"algorithm":m.getAlogrithmSid()})}
fn state(p:&KmoBookProtect)->Value{json!({"default":p.isDefaultBookProtect(),"window":p.getLockWindow(),"structure":p.getLockStructure(),"password":p.getPassword(),"verifier":p.getSha512Password().map(|m|verifier(&m.borrow())),"protected":p.isBookProtected(),"revision":p.isLockRevion(),"revisionPassword":p.getRevisionPassword()})}
fn reset(p:&KmoBookProtect){p.setPassword(0);p.setPassword__verifier(None);p.setLockWindow(false);p.setLockStructure(false);p.setLockRevion(false);p.setRevisionPassword(0);}
struct Listener{book:Rc<KmoBook>,p:Rc<KmoBookProtect>,events:Rc<RefCell<Vec<Value>>>}
impl KmoBookChangeEventsListener for Listener{fn bookDidFinishInitializing(&self){}fn bookContentsDidFinishChanging(&self){}fn sheetDidFinishActivating(&self){}fn bookSettingsDidFinishChanging(&self){self.events.borrow_mut().push(json!({"dirty":self.book.isDirty(),"state":state(&self.p)}));}}
fn command(p:&KmoBookProtect,book:&KmoBook,a:&Value)->Value{match a["op"].as_str().unwrap(){"int"=>p.setPassword(a["value"].as_i64().unwrap()as i32),"string"=>p.setPassword__string(a["value"].as_str()),"window"=>p.setLockWindow(a["value"].as_bool().unwrap()),"structure"=>p.setLockStructure(a["value"].as_bool().unwrap()),"revision"=>p.setLockRevion(a["value"].as_bool().unwrap()),"revisionPassword"=>p.setRevisionPassword(a["value"].as_i64().unwrap()as i32),"cancel"=>p.cancelBookProtected(),"check"=>return json!(p.checkPassword(a["value"].as_str())),"correct"=>return json!(p.isCorrectPassword(a["value"].as_str())),"revisionCheck"=>return json!(p.isCorrectRevisionPassword(a["value"].as_str())),"verifier"=>p.setPassword__verifier(if a["null"]==true{None}else{Some(Rc::new(RefCell::new(ModifyVerifier::new_with_algorithm__nullable(a["hash"].as_str(),a["salt"].as_str(),a["spin"].as_i64().unwrap()as i32,a["algorithm"].as_i64().unwrap()as i32))))}),"mutateVerifier"=>p.getSha512Password().expect("NullPointerException").borrow_mut().setHashData("changed"),"dirtyFalse"=>book.setDirty(false),s=>panic!("unknown {s}")}Value::Null}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_book_protection_notifications_and_xml(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/book-protect-r0b62");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let actual=book.getBookProtect();let mut histories=vec![];for h in input["histories"].as_array().unwrap(){reset(&actual);book.setDirty(false);let events=Rc::new(RefCell::new(vec![]));let listener:Rc<dyn KmoBookChangeEventsListener>=Rc::new(Listener{book:book.clone(),p:actual.clone(),events:events.clone()});book.subscribeChangeEvents(Some(listener.clone()));let local=if h["nullBook"]==true{Rc::new(KmoBookProtect::new(Weak::new()))}else{actual.clone()};let mut rows=vec![];for a in h["commands"].as_array().unwrap(){let mut row=call(||command(&local,&book,a));row["state"]=state(&local);row["dirty"]=json!(book.isDirty());row["events"]=json!(events.borrow().clone());rows.push(row);}book.unsubscribeChangeEvents(Some(&listener));histories.push(rows);}
 let mut xml=vec![];for s in input["xml"].as_array().unwrap(){reset(&actual);book.setDirty(false);let s=s.as_str().unwrap();let mut row=call(||{UnifiedXmlReader::read(&mut std::io::Cursor::new(s.as_bytes()),Box::new(WorkbookHandler::WorkbookHandler(book.clone(),XlsxrWorkbook::XlsxrWorkbook(book.clone(),None,None,None)))).unwrap();Value::Null});row["state"]=state(&actual);row["dirty"]=json!(book.isDirty());xml.push(row);}reset(&actual);let interface:Rc<dyn IKmoBookProtect>=actual.clone();let out=json!({"hexBmp":(0..65536).filter_map(char::from_u32).map(|c|ValueHelper::hexStringToInt(Some(&c.to_string()))).collect::<Vec<_>>(),"hex":input["hex"].as_array().unwrap().iter().map(|s|ValueHelper::hexStringToInt(s.as_str())).collect::<Vec<_>>(),"histories":histories,"sameFacade":Rc::ptr_eq(&interface,&book.getBookProtection()),"xml":xml});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();compare(&out,&java,"root");}
